 * Calm Bookmarks — production server.
 * REST API + static frontend. Behaviour follows the approved scenarios SCN-001..SCN-022
 * (see SCENARIO-MAP.md). Search/filter/sort/paginate happen in the browser for a live feel;
 * the server owns persistence, metadata fetch, preserved copies, Internet Archive, import/export.
 */
const express = require("express");
const fs = require("fs");
const path = require("path");
const store = require("./lib/store");
const meta = require("./lib/metadata");
const bh = require("./lib/bookmarksHtml");

const app = express();
app.use(express.json({ limit: "20mb" }));
app.use(express.text({ type: ["text/html", "text/plain"], limit: "20mb" }));

let state = store.load();
function persist() { store.save(state); }
function nextId() {
  const ids = state.bookmarks.map((b) => b.id).concat(state.collections.map((c) => c.id));
  return (ids.length ? Math.max(...ids) : 0) + 1;
}
const today = () => new Date().toISOString().slice(0, 10);
function find(id) { return state.bookmarks.find((b) => b.id === Number(id)); }

// --- read whole state ---
app.get("/api/state", (req, res) => res.json(state));

// --- metadata for the editor's auto-fill (SCN-001, SCN-011) ---
app.post("/api/fetch", async (req, res) => {
  const url = (req.body && req.body.url || "").trim();
  if (!store.looksLikeLink(url)) return res.status(400).json({ error: "not_a_link" });
  const m = await meta.fetchMetadata(url);
  res.json(m);
});

async function applyCopyAndIA(b, keepCopy, ia) {
  b.keepCopy = !!keepCopy;
  b.copyKind = null; b.capturedAt = null; b.copyFailed = false;
  if (keepCopy) {
    try {
      const r = await meta.captureSnapshot(String(b.id), b.url);
      b.copyKind = r.copyKind; b.capturedAt = r.capturedAt; b.copyFailed = false;
    } catch (e) { b.copyFailed = true; }
  }
  b.iaUrl = b.iaUrl || null;
  if (ia && !b.iaUrl) {
    try { b.iaUrl = await meta.submitInternetArchive(b.url); }
    catch (e) { b.iaError = true; }
  }
}

// --- create (SCN-001, SCN-003 duplicate, SCN-012 invalid, SCN-020 copy/IA) ---
app.post("/api/bookmarks", async (req, res) => {
  const body = req.body || {};
  const url = (body.url || "").trim();
  if (!store.looksLikeLink(url)) return res.status(400).json({ error: "not_a_link" });
  const existing = state.bookmarks.find((b) => store.normUrl(b.url) === store.normUrl(url));
  if (existing) return res.status(409).json({ error: "duplicate", existing });

  const b = {
    id: nextId(),
    url,
    domain: store.domainOf(url),
    title: (body.title || "").trim() || url,
    desc: (body.desc || "").trim(),
    note: (body.note || "").trim(),
    tags: Array.isArray(body.tags) ? body.tags.filter(Boolean) : [],
    readLater: body.readLater !== false,
    archived: false,
    addedAt: today(),
    preview: body.preview || null,
    favicon: body.favicon || null,
    iaUrl: null,
  };
  await applyCopyAndIA(b, body.keepCopy !== false, !!body.ia);
  state.bookmarks.unshift(b);
  persist();
  res.status(201).json({ bookmark: b });
});

// --- update, incl. address change with clash safeguard (SCN-004) ---
app.put("/api/bookmarks/:id", async (req, res) => {
  const b = find(req.params.id);
  if (!b) return res.status(404).json({ error: "not_found" });
  const body = req.body || {};
  const newUrl = (body.url != null ? body.url : b.url).trim();
  if (!store.looksLikeLink(newUrl)) return res.status(400).json({ error: "not_a_link" });
  const clash = state.bookmarks.find((x) => x.id !== b.id && store.normUrl(x.url) === store.normUrl(newUrl));
  if (clash) return res.status(409).json({ error: "duplicate", existing: clash });

  const urlChanged = store.normUrl(newUrl) !== store.normUrl(b.url);
  b.url = newUrl;
  b.domain = store.domainOf(newUrl);
  if (body.title != null) b.title = body.title.trim() || newUrl;
  if (body.desc != null) b.desc = body.desc.trim();
  if (body.note != null) b.note = body.note.trim();
  if (Array.isArray(body.tags)) b.tags = body.tags.filter(Boolean);
  if (body.readLater != null) b.readLater = !!body.readLater;

  // Copy/IA: (re)capture if newly requested or address changed
  if (body.keepCopy != null) {
    if (body.keepCopy && (urlChanged || !b.capturedAt)) await applyCopyAndIA(b, true, false);
    else if (!body.keepCopy) { b.keepCopy = false; }
  } else if (urlChanged && b.keepCopy) {
    await applyCopyAndIA(b, true, false);
  }
  if (body.ia && !b.iaUrl) {
    try { b.iaUrl = await meta.submitInternetArchive(b.url); } catch (e) { b.iaError = true; }
  }
  persist();
  res.json({ bookmark: b });
});

// --- delete permanently (SCN-017) ---
app.delete("/api/bookmarks/:id", (req, res) => {
  const b = find(req.params.id);
  if (!b) return res.status(404).json({ error: "not_found" });
  state.bookmarks = state.bookmarks.filter((x) => x.id !== b.id);
  for (const ext of ["html", "pdf"]) {
    const f = path.join(store.SNAP_DIR, b.id + "." + ext);
    if (fs.existsSync(f)) fs.unlinkSync(f);
  }
  persist();
  res.json({ ok: true });
});

// --- retry capturing a preserved copy (SCN-020) ---
app.post("/api/bookmarks/:id/capture", async (req, res) => {
  const b = find(req.params.id);
  if (!b) return res.status(404).json({ error: "not_found" });
  b.keepCopy = true;
  try {
    const r = await meta.captureSnapshot(String(b.id), b.url);
    b.copyKind = r.copyKind; b.capturedAt = r.capturedAt; b.copyFailed = false;
  } catch (e) { b.copyFailed = true; b.capturedAt = null; }
  persist();
  res.json({ bookmark: b });
});

// --- bulk actions (SCN-016) ---
app.post("/api/bulk", (req, res) => {
  const { ids = [], op, value } = req.body || {};
  const idSet = new Set(ids.map(Number));
  const sel = state.bookmarks.filter((b) => idSet.has(b.id));
  switch (op) {
    case "read": sel.forEach((b) => (b.readLater = false)); break;
    case "unread": sel.forEach((b) => (b.readLater = true)); break;
    case "archive": sel.forEach((b) => (b.archived = true)); break;
    case "restore": sel.forEach((b) => (b.archived = false)); break;
    case "delete":
      state.bookmarks = state.bookmarks.filter((b) => !idSet.has(b.id));
      sel.forEach((b) => { for (const ext of ["html", "pdf"]) { const f = path.join(store.SNAP_DIR, b.id + "." + ext); if (fs.existsSync(f)) fs.unlinkSync(f); } });
      break;
    case "addLabel":
      if (value) sel.forEach((b) => { b.tags = b.tags || []; if (!b.tags.some((t) => t.toLowerCase() === value.toLowerCase())) b.tags.push(value); });
      break;
    case "removeLabel":
      if (value) sel.forEach((b) => { b.tags = (b.tags || []).filter((t) => t.toLowerCase() !== value.toLowerCase()); });
      break;
    default: return res.status(400).json({ error: "bad_op" });
  }
  persist();
  res.json({ ok: true });
});

// --- serve a preserved copy (SCN-020) ---
app.get("/api/snapshot/:id", (req, res) => {
  const b = find(req.params.id);
  const htmlF = path.join(store.SNAP_DIR, req.params.id + ".html");
  const pdfF = path.join(store.SNAP_DIR, req.params.id + ".pdf");
  if (fs.existsSync(pdfF)) { res.type("application/pdf"); return res.sendFile(pdfF); }
  if (fs.existsSync(htmlF)) { res.type("text/html"); return res.sendFile(htmlF); }
  res.status(404).send("No preserved copy for this bookmark" + (b ? "" : " (unknown bookmark)") + ".");
});

// --- export whole collection incl. archived (SCN-021) ---
app.get("/api/export", (req, res) => {
  res.setHeader("Content-Disposition", 'attachment; filename="bookmarks.html"');
  res.type("text/html");
  res.send(bh.generate(state.bookmarks));
});

// --- import standard bookmark HTML (SCN-021) ---
app.post("/api/import", (req, res) => {
  const html = typeof req.body === "string" ? req.body : (req.body && req.body.html) || "";
  const items = bh.parse(html);
  let added = 0, skipped = 0;
  for (const it of items) {
    if (state.bookmarks.some((b) => store.normUrl(b.url) === store.normUrl(it.url))) { skipped++; continue; }
    state.bookmarks.push({
      id: nextId(),
      url: it.url,
      domain: store.domainOf(it.url),
      title: it.title || it.url,
      desc: "",
      note: "",
      tags: it.tags || [],
      readLater: true,
      archived: false,
      addedAt: it.addedAt || today(),
      keepCopy: false, copyKind: null, capturedAt: null, copyFailed: false, iaUrl: null,
    });
    added++;
  }
  persist();
  res.json({ added, skipped });
});

// --- collections (SCN-018) ---
app.post("/api/collections", (req, res) => {
  const { name, query } = req.body || {};
  if (!name) return res.status(400).json({ error: "name_required" });
  const c = { id: nextId(), name: String(name).trim(), query: String(query || "").trim() };
  state.collections.push(c);
  persist();
  res.status(201).json({ collection: c });
});
app.delete("/api/collections/:id", (req, res) => {
  state.collections = state.collections.filter((c) => c.id !== Number(req.params.id));
  persist();
  res.json({ ok: true });
});

// --- preferences (SCN-014 sort, SCN-022 text size / items shown) ---
app.put("/api/prefs", (req, res) => {
  state.prefs = { ...state.prefs, ...(req.body || {}) };
  persist();
  res.json({ prefs: state.prefs });
});

app.use(express.static(path.join(__dirname, "public")));
app.get("/", (req, res) => res.sendFile(path.join(__dirname, "public", "index.html")));

const PORT = process.env.PORT || 4000;
const HOST = "0.0.0.0";
if (require.main === module) {
  app.listen(PORT, HOST, () => console.log(`Calm Bookmarks running on http://${HOST}:${PORT}`));
}
module.exports = app;
/*
 * Simple durable JSON store: { bookmarks, collections, prefs }.
 * Single-user app; synchronous file IO is adequate and keeps the design simple.
 */
const fs = require("fs");
const path = require("path");

const DATA_DIR = process.env.BM_DATA_DIR || path.join(__dirname, "..", "data");
const DB_FILE = path.join(DATA_DIR, "db.json");
const SNAP_DIR = path.join(DATA_DIR, "snapshots");

const DEFAULT_PREFS = { sort: "newest", pageSize: "25", fontSize: "medium" };

function ensureDirs() {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  fs.mkdirSync(SNAP_DIR, { recursive: true });
}

function load() {
  ensureDirs();
  if (!fs.existsSync(DB_FILE)) {
    return { bookmarks: [], collections: [], prefs: { ...DEFAULT_PREFS } };
  }
  try {
    const raw = JSON.parse(fs.readFileSync(DB_FILE, "utf8"));
    return {
      bookmarks: raw.bookmarks || [],
      collections: raw.collections || [],
      prefs: { ...DEFAULT_PREFS, ...(raw.prefs || {}) },
    };
  } catch (e) {
    return { bookmarks: [], collections: [], prefs: { ...DEFAULT_PREFS } };
  }
}

function save(state) {
  ensureDirs();
  fs.writeFileSync(DB_FILE, JSON.stringify(state, null, 2));
}

// Address normalisation used for duplicate detection (SCN-003, SCN-004, SCN-021).
function normUrl(u) {
  return String(u || "")
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .replace(/\/+$/, "");
}

function looksLikeLink(u) {
  const s = String(u || "").trim();
  if (!s || /\s/.test(s)) return false;
  return /^https?:\/\//i.test(s) || /\.[a-z]{2,}/i.test(s);
}

function domainOf(url) {
  try {
    const u = /^https?:\/\//i.test(url) ? url : "https://" + url;
    return new URL(u).hostname.replace(/^www\./, "");
  } catch (e) {
    return "";
  }
}

module.exports = { load, save, normUrl, looksLikeLink, domainOf, DATA_DIR, SNAP_DIR, DB_FILE, DEFAULT_PREFS };
/*
 * Page metadata fetch (auto-fill, SCN-001/011), preserved-copy capture (SCN-020),
 * and best-effort Internet Archive submission (SCN-020).
 * All network operations degrade gracefully: on failure the caller still saves the
 * bookmark and surfaces a retryable state.
 */
const fs = require("fs");
const path = require("path");
const { SNAP_DIR, domainOf } = require("./store");

const UA = "CalmBookmarks/1.0 (+bookmark manager)";
const TIMEOUT = 8000;

function pick(re, html) {
  const m = html.match(re);
  return m ? m[1].trim() : "";
}

function decode(s) {
  return String(s || "")
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}

// Fetch title/description/preview image/favicon for the editor's auto-fill.
async function fetchMetadata(url) {
  const full = /^https?:\/\//i.test(url) ? url : "https://" + url;
  const domain = domainOf(full);
  try {
    const res = await fetch(full, { headers: { "User-Agent": UA }, signal: AbortSignal.timeout(TIMEOUT), redirect: "follow" });
    const ct = (res.headers.get("content-type") || "").toLowerCase();
    const isPdf = ct.includes("application/pdf") || /\.pdf($|\?)/i.test(full);
    if (isPdf) {
      return { readable: true, isPdf: true, title: decodeURIComponent(full.split("/").pop()) || "PDF document", desc: "", preview: null, favicon: null, domain };
    }
    if (!res.ok) return { readable: false, isPdf: false, domain };
    const html = (await res.text()).slice(0, 500000);
    const ogTitle = decode(pick(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i, html));
    const title = decode(ogTitle || pick(/<title[^>]*>([\s\S]*?)<\/title>/i, html)).replace(/\s+/g, " ").trim();
    const desc = decode(
      pick(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i, html) ||
      pick(/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i, html)
    );
    let preview = pick(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i, html) || null;
    if (preview && preview.startsWith("//")) preview = "https:" + preview;
    if (preview && preview.startsWith("/")) preview = new URL(preview, full).href;
    const favicon = "https://www.google.com/s2/favicons?domain=" + encodeURIComponent(domain) + "&sz=64";
    return { readable: true, isPdf: false, title: title || domain, desc, preview, favicon, domain };
  } catch (e) {
    return { readable: false, isPdf: false, domain };
  }
}

// Capture a preserved copy. Returns { copyKind, capturedAt } or throws on failure.
async function captureSnapshot(id, url) {
  const full = /^https?:\/\//i.test(url) ? url : "https://" + url;
  const res = await fetch(full, { headers: { "User-Agent": UA }, signal: AbortSignal.timeout(TIMEOUT), redirect: "follow" });
  if (!res.ok) throw new Error("fetch failed: " + res.status);
  const ct = (res.headers.get("content-type") || "").toLowerCase();
  const isPdf = ct.includes("application/pdf") || /\.pdf($|\?)/i.test(full);
  if (isPdf) {
    const buf = Buffer.from(await res.arrayBuffer());
    fs.writeFileSync(path.join(SNAP_DIR, id + ".pdf"), buf);
    return { copyKind: "pdf", capturedAt: new Date().toISOString().slice(0, 10) };
  }
  let html = await res.text();
  const banner =
    `<!-- Preserved copy saved by Calm Bookmarks on ${new Date().toISOString().slice(0, 10)} from ${full} -->\n` +
    `<base href="${full}">\n`;
  // Keep the copy self-contained enough to read: absolute base + saved markup.
  html = banner + html;
  fs.writeFileSync(path.join(SNAP_DIR, id + ".html"), html);
  return { copyKind: "page", capturedAt: new Date().toISOString().slice(0, 10) };
}

// Best-effort submission to the Internet Archive. Returns a wayback URL or throws.
async function submitInternetArchive(url) {
  const full = /^https?:\/\//i.test(url) ? url : "https://" + url;
  const res = await fetch("https://web.archive.org/save/" + full, {
    method: "GET",
    headers: { "User-Agent": UA },
    signal: AbortSignal.timeout(20000),
    redirect: "follow",
  });
  if (!res.ok && res.status !== 302) throw new Error("IA save failed: " + res.status);
  const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, "");
  return "https://web.archive.org/web/" + stamp + "/" + full;
}

module.exports = { fetchMetadata, captureSnapshot, submitInternetArchive };
/*
 * Import/export of the standard Netscape bookmark HTML format (SCN-021).
 * Import preserves title, labels (folder path + TAGS, de-duplicated case-insensitively),
 * and the added date. Export writes the whole collection preserving titles, labels, dates.
 */

function escapeHtml(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function decodeEntities(s) {
  return String(s || "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, " ");
}

function mergeLabels(list) {
  const out = [];
  const seen = new Set();
  for (const t of list) {
    if (!t) continue;
    const k = t.toLowerCase();
    if (!seen.has(k)) { seen.add(k); out.push(t); }
  }
  return out;
}

// Parse a Netscape bookmark HTML string into [{ url, title, tags, addedAt }].
function parse(html) {
  const items = [];
  const folderStack = [];
  let pendingFolder = null;
  const re = /<h3[^>]*>([\s\S]*?)<\/h3>|<dl[^>]*>|<\/dl>|<a\s+([^>]*)>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = re.exec(html))) {
    if (m[1] !== undefined) {
      pendingFolder = decodeEntities(m[1].replace(/<[^>]*>/g, "").trim());
    } else if (/^<dl/i.test(m[0])) {
      folderStack.push(pendingFolder);
      pendingFolder = null;
    } else if (/^<\/dl/i.test(m[0])) {
      folderStack.pop();
    } else if (m[2] !== undefined) {
      const attrs = m[2];
      const title = decodeEntities(m[3].replace(/<[^>]*>/g, "").trim());
      const href = (attrs.match(/href\s*=\s*"([^"]*)"/i) || [])[1];
      if (!href || !/^https?:/i.test(href)) continue;
      const addDate = (attrs.match(/add_date\s*=\s*"(\d+)"/i) || [])[1];
      const tagAttr = (attrs.match(/tags\s*=\s*"([^"]*)"/i) || [])[1] || "";
      const tagList = tagAttr.split(",").map((s) => s.trim()).filter(Boolean);
      const folders = folderStack.filter(Boolean);
      const tags = mergeLabels([...tagList, ...folders]);
      const addedAt = addDate
        ? new Date(parseInt(addDate, 10) * 1000).toISOString().slice(0, 10)
        : null;
      items.push({ url: href, title: title || href, tags, addedAt });
    }
  }
  return items;
}

// Generate a Netscape bookmark HTML string for the whole collection.
function generate(bookmarks) {
  const rows = bookmarks
    .map((b) => {
      const secs = b.addedAt ? Math.floor(new Date(b.addedAt).getTime() / 1000) : Math.floor(Date.now() / 1000);
      const tags = (b.tags || []).join(",");
      const tagAttr = tags ? ` TAGS="${escapeHtml(tags)}"` : "";
      return `    <DT><A HREF="${escapeHtml(b.url)}" ADD_DATE="${secs}"${tagAttr}>${escapeHtml(b.title)}</A>`;
    })
    .join("\n");
  return (
    "<!DOCTYPE NETSCAPE-Bookmark-file-1>\n" +
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n' +
    "<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n" +
    rows +
    "\n</DL><p>\n"
  );
}

module.exports = { parse, generate, mergeLabels, escapeHtml };
/*
 * Search query language for bookmarks.
 * Implements SCN-006 (broad, case-insensitive, implicit-AND search) and
 * SCN-007 (#labels, "phrases", AND/OR/NOT, parentheses, quoted operators literal).
 * Shared by the browser (window.BMQuery) and Node tests (module.exports).
