     6	
     7	function escapeHtml(s) {
     8	  return String(s || "")
     9	    .replace(/&/g, "&amp;")
    10	    .replace(/</g, "&lt;")
    11	    .replace(/>/g, "&gt;")
    12	    .replace(/"/g, "&quot;");
    13	}
    14	
    15	function decodeEntities(s) {
    16	  return String(s || "")
    17	    .replace(/&amp;/g, "&")
    18	    .replace(/&lt;/g, "<")
    19	    .replace(/&gt;/g, ">")
    20	    .replace(/&quot;/g, '"')
    21	    .replace(/&#39;/g, "'")
    22	    .replace(/&nbsp;/g, " ");
    23	}
    24	
    25	function mergeLabels(list) {
    26	  const out = [];
    27	  const seen = new Set();
    28	  for (const t of list) {
    29	    if (!t) continue;
    30	    const k = t.toLowerCase();
    31	    if (!seen.has(k)) { seen.add(k); out.push(t); }
    32	  }
    33	  return out;
    34	}
