    36	// Parse a Netscape bookmark HTML string into [{ url, title, tags, addedAt }].
    37	function parse(html) {
    38	  const items = [];
    39	  const folderStack = [];
    40	  let pendingFolder = null;
    41	  const re = /<h3[^>]*>([\s\S]*?)<\/h3>|<dl[^>]*>|<\/dl>|<a\s+([^>]*)>([\s\S]*?)<\/a>/gi;
    42	  let m;
    43	  while ((m = re.exec(html))) {
    44	    if (m[1] !== undefined) {
    45	      pendingFolder = decodeEntities(m[1].replace(/<[^>]*>/g, "").trim());
    46	    } else if (/^<dl/i.test(m[0])) {
    47	      folderStack.push(pendingFolder);
    48	      pendingFolder = null;
    49	    } else if (/^<\/dl/i.test(m[0])) {
    50	      folderStack.pop();
    51	    } else if (m[2] !== undefined) {
    52	      const attrs = m[2];
    53	      const title = decodeEntities(m[3].replace(/<[^>]*>/g, "").trim());
    54	      const href = (attrs.match(/href\s*=\s*"([^"]*)"/i) || [])[1];
    55	      if (!href || !/^https?:/i.test(href)) continue;
    56	      const addDate = (attrs.match(/add_date\s*=\s*"(\d+)"/i) || [])[1];
    57	      const tagAttr = (attrs.match(/tags\s*=\s*"([^"]*)"/i) || [])[1] || "";
    58	      const tagList = tagAttr.split(",").map((s) => s.trim()).filter(Boolean);
    59	      const folders = folderStack.filter(Boolean);
    60	      const tags = mergeLabels([...tagList, ...folders]);
    61	      const addedAt = addDate
    62	        ? new Date(parseInt(addDate, 10) * 1000).toISOString().slice(0, 10)
    63	        : null;
    64	      items.push({ url: href, title: title || href, tags, addedAt });
    65	    }
    66	  }
    67	  return items;
    68	}
