    70	// Generate a Netscape bookmark HTML string for the whole collection.
    71	function generate(bookmarks) {
    72	  const rows = bookmarks
    73	    .map((b) => {
    74	      const secs = b.addedAt ? Math.floor(new Date(b.addedAt).getTime() / 1000) : Math.floor(Date.now() / 1000);
    75	      const tags = (b.tags || []).join(",");
    76	      const tagAttr = tags ? ` TAGS="${escapeHtml(tags)}"` : "";
    77	      return `    <DT><A HREF="${escapeHtml(b.url)}" ADD_DATE="${secs}"${tagAttr}>${escapeHtml(b.title)}</A>`;
    78	    })
    79	    .join("\n");
    80	  return (
    81	    "<!DOCTYPE NETSCAPE-Bookmark-file-1>\n" +
    82	    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n' +
    83	    "<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n" +
    84	    rows +
    85	    "\n</DL><p>\n"
    86	  );
    87	}
